import { IMAGE_WIDTHS } from "../lib/images.js";

/** Pairs each generated file with its real pixel width (small crops aren't upscaled). */
function sources(name, width, ext) {
  const out = IMAGE_WIDTHS.filter((w) => w < width).map((w) => `/images/${name}-${w}.${ext} ${w}w`);
  const next = IMAGE_WIDTHS.find((w) => w >= width);
  if (next) out.push(`/images/${name}-${next}.${ext} ${width}w`);
  return out.join(", ");
}

/** Responsive grayscale AVIF/WebP/JPEG image generated by `npm run images`. */
export default function Picture({ name, alt, width, height, sizes, position, className = "", priority }) {
  const fallback = IMAGE_WIDTHS.find((w) => w >= Math.min(width, 800)) ?? IMAGE_WIDTHS[0];
  return (
    <picture className="contents">
      <source type="image/avif" srcSet={sources(name, width, "avif")} sizes={sizes} />
      <source type="image/webp" srcSet={sources(name, width, "webp")} sizes={sizes} />
      <img
        src={`/images/${name}-${fallback}.jpg`}
        srcSet={sources(name, width, "jpg")}
        sizes={sizes}
        alt={alt}
        width={width}
        height={height}
        decoding="async"
        loading={priority ? "eager" : "lazy"}
        // React 18 passes this through only in lowercase
        // eslint-disable-next-line react/no-unknown-property
        fetchpriority={priority ? "high" : undefined}
        style={position ? { objectPosition: position } : undefined}
        className={`mono-img object-cover ${className}`}
      />
    </picture>
  );
}
